on><?php endforeach; ?></select></div><div><label class="label">Proveedor *</label><input name="nombre" class="input" required maxlength="150" value="<?= e($integration['nombre']) ?>"></div><div class="sm:col-span-2"><label class="label">Endpoint HTTPS · puerto 443 *</label><input type="url" name="endpoint" class="input" required value="<?= e($integration['endpoint']) ?>"></div><div><label class="label">Método</label><select name="metodo" class="input"><?php foreach(['POST','PUT','PATCH'] as $method): ?><option <?= $integration['metodo']===$method?'selected':'' ?>><?= $method ?></option><?php endforeach; ?></select></div><div><label class="label">Autenticación</label><select name="autenticacion" class="input"><option value="Bearer" <?= $integration['autenticacion']==='Bearer'?'selected':'' ?>>Authorization: Bearer</option><option value="X-API-Key" <?= $integration['autenticacion']==='X-API-Key'?'selected':'' ?>>X-API-Key</option></select></div><div><label class="label">Nueva credencial</label><input type="password" name="credencial" class="input" autocomplete="new-password" placeholder="Vacío: conservar la actual"></div><div><label class="label">Ruta JSON de referencia no sensible</label><input name="ruta_referencia" class="input" value="<?= e($integration['ruta_referencia']) ?>" placeholder="data.radicado"></div><div class="sm:col-span-2 flex justify-end"><button class="btn-primary">Guardar cambios</button></div></form></details><details class="rounded-2xl border border-blue-100 bg-blue-50/40"><summary class="cursor-pointer list-none p-4 text-xs font-semibold text-blue-800">Preparar una solicitud HTTPS real</summary><form method="post" action="<?= e(url('/integraciones/'.$integration['id'].'/ejecutar')) ?>" class="space-y-4 border-t border-blue-100 p-4" data-confirm="Esto contactará al proveedor con los datos suministrados. ¿Confirmas la operación externa real?"><?= csrf_field() ?><div><label class="label">Operación y referencia interna *</label><input name="operacion" class="input" required maxlength="250" placeholder="Ej.: envío de reporte asociado al evento interno registrado"></div><div><label class="label">Payload JSON según contrato oficial *</label><textarea name="payload" class="input min-h-40 font-mono text-xs" required spellcheck="false" placeholder='{"campo":"valor real definido por el proveedor"}'></textarea><p class="mt-1 text-[10px] leading-4 text-slate-500">Verifica campos, autorización y minimización de datos. El contenido no se recupera después de enviarlo. No uses este conector para historias clínicas.</p></div><button class="btn-primary" <?= !$integration['activo']?'disabled':'' ?>><?= icon('arrow-right','h-4 w-4') ?> Ejecutar solicitud real</button></form></details></div></article><?php endforeach; ?></section>
<details id="nueva-integracion" class="ios-card mt-6 overflow-hidden"><summary class="cursor-pointer list-none p-5 text-sm font-semibold">Configurar nuevo conector</summary><form method="post" action="<?= e(url('/integraciones')) ?>" class="grid gap-4 border-t border-slate-100 p-5 sm:grid-cols-2 lg:grid-cols-3"><?= csrf_field() ?><div><label class="label">Tipo *</label><select name="tipo" class="input"><?php foreach($types as $type): ?><option><?= e($type) ?></option><?php endforeach; ?></select></div><div><label class="label">Nombre del proveedor *</label><input name="nombre" class="input" required maxlength="150"></div><div><label class="label">Método</label><select name="metodo" class="input"><option>POST</option><option>PUT</option><option>PATCH</option></select></div><div class="sm:col-span-2"><label class="label">Endpoint HTTPS · sin query ni credenciales en URL *</label><input type="url" name="endpoint" class="input" required placeholder="https://api.proveedor-oficial.co/recurso"></div><div><label class="label">Autenticación</label><select name="autenticacion" class="input"><option value="Bearer">Authorization: Bearer</option><option value="X-API-Key">X-API-Key</option></select></div><div><label class="label">Credencial real *</label><input type="password" name="credencial" class="input" required autocomplete="new-password"></div><div><label class="label">Ruta de referencia JSON</label><input name="ruta_referencia" class="input" placeholder="data.radicado"><p class="mt-1 text-[10px] text-slate-400">Sólo un identificador no sensible de la respuesta.</p></div><div class="flex items-end"><button class="btn-primary">Guardar sin conectar</button></div></form></details>
<section id="ejecuciones" class="ios-card mt-6 overflow-hidden"><div class="border-b border-slate-100 p-5"><h2 class="text-base font-semibold">Historial técnico y validación documental</h2><p class="mt-1 text-xs text-slate-500">Las huellas permiten comprobar integridad si conservas el intercambio en el canal autorizado; esta plataforma no almacena sus cuerpos.</p></div><div class="divide-y divide-slate-100"><?php if(!$executions): ?><div class="p-8 text-center text-xs text-slate-400">Todavía no se ha realizado ninguna solicitud.</div><?php endif; ?><?php foreach($executions as $execution): ?><article id="ejecucion-<?= (int)$execution['id'] ?>" class="p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><div class="flex flex-wrap items-center gap-2"><span class="badge <?= $execution['estado_tecnico']==='Respuesta HTTPS'?'badge-blue':($execution['estado_tecnico']==='En curso'?'badge-yellow':'badge-red') ?>"><?= e($execution['estado_tecnico']) ?></span><?php if($execution['verificado_at']): ?><span class="badge badge-green">Soporte verificado</span><?php endif; ?><h3 class="text-xs font-semibold"><?= e($execution['proveedor']) ?> · <?= e($execution['tipo']) ?></h3></div><p class="mt-2 text-xs text-slate-600"><?= e($execution['operacion']) ?></p><p class="mt-1 text-[10px] text-slate-400"><?= format_date($execution['ejecutado_at'],true) ?> · <?= e($execution['ejecutado_por_nombre']??'usuario no disponible') ?> · HTTP <?= $execution['http_status']!==null?(int)$execution['http_status']:'sin respuesta' ?> · <?= (int)$execution['duracion_ms'] ?> ms · <?= (int)$execution['bytes_respuesta'] ?> bytes recibidos</p></div><div class="flex flex-wrap gap-2"><a href="<?= e(url('/evidencias?vinculo='.rawurlencode('integracion_ejecucion:'.$execution['id']).'#cargar')) ?>" class="btn-secondary"><?= icon('upload','h-4 w-4') ?> Acuse / soporte</a><?php if(!$execution['verificado_at'] && $execution['estado_tecnico']!=='En curso'): ?><form method="post" action="<?= e(url('/integraciones/ejecuciones/'.$execution['id'].'/verificar')) ?>"><?= csrf_field() ?><button class="btn-secondary">Validar soporte revisado</button></form><?php endif; ?></div></div><p class="mt-3 text-xs leading-5 text-slate-500"><?= e($execution['detalle']) ?></p><div class="mt-3 grid gap-2 rounded-xl bg-slate-50 p-3 font-mono text-[10px] break-all text-slate-500 sm:grid-cols-2"><p><strong>Correlación:</strong> <?= e($execution['correlacion']) ?></p><p><strong>Referencia externa:</strong> <?= e($execution['referencia_externa']?:'No configurada o no recibida') ?></p><p><strong>Solicitud SHA-256:</strong> <?= e($execution['solicitud_sha256']) ?></p><p><strong>Respuesta SHA-256:</strong> <?= e($execution['respuesta_sha256']?:'Sin cuerpo') ?></p></div><?php if($execution['verificado_at']): ?><p class="mt-2 text-[10px] text-emerald-700">Soporte validado por <?= e($execution['verificado_por_nombre']??'usuario autorizado') ?> el <?= format_date($execution['verificado_at'],true) ?>. Esta validación documental no altera la respuesta técnica.</p><?php endif; ?></article><?php endforeach; ?></div></section>
